"""Monte Carlo launch-risk simulation.

Design notes
------------
* Every trial produces a schedule generated by the serial SGS scheduler, which
  respects precedence, resource capacity and material release dates.  We never
  fall back silently to an unconstrained CPM schedule.
* Inputs are sampled with *entity-keyed* random streams, so two scenarios that
  share task/supplier IDs consume the same random numbers (common random
  numbers).  Paired comparisons therefore isolate the intervention effect.
* Sampling uncertainty (SEM, confidence intervals) is reported separately from
  input uncertainty; the UI never presents simulated probabilities as facts.
"""
from __future__ import annotations

import hashlib
import math
import time
from dataclasses import dataclass
from typing import Callable

import numpy as np
from scipy import stats

from app.scheduling.cpm import CpmResult, compute_cpm
from app.scheduling.cpsat import CpsatOptions, resource_constrained_schedule
from app.scheduling.model import PlanningModel, TaskNode
from app.scheduling.sgs import schedule_sgs
from app.simulation.context import SimulationContext
from app.simulation.distributions import (
    DurationParams,
    InvalidDistribution,
    make_params,
)

ENGINE_VERSION = "1.2.0"
PERCENTILE_METHOD = "linear interpolation between order statistics (NumPy method='linear')"
RETEST_DAY_COST = 3500.0
ECO_LABOR_DAY_COST = 1200.0


class SimulationCancelled(RuntimeError):
    pass


@dataclass
class SimulationOptions:
    iterations: int = 2000
    seed: int = 42
    correlation_rho: float = 0.6
    capacity_loss_prob: float = 0.02
    absenteeism_prob: float = 0.02
    transport_delay_prob: float = 0.015
    supplier_disruption_enabled: bool = True
    material_constraints_enabled: bool = True
    validate_iterations: int = 0
    solver_time_limit: float = 3.0
    progress_callback: Callable[[float, str], None] | None = None
    cancel_check: Callable[[], bool] | None = None
    label: str = "Monte Carlo"

    def to_dict(self) -> dict:
        data = {
            "iterations": self.iterations,
            "seed": self.seed,
            "correlation_rho": self.correlation_rho,
            "capacity_loss_prob": self.capacity_loss_prob,
            "absenteeism_prob": self.absenteeism_prob,
            "transport_delay_prob": self.transport_delay_prob,
            "supplier_disruption_enabled": self.supplier_disruption_enabled,
            "material_constraints_enabled": self.material_constraints_enabled,
            "validate_iterations": self.validate_iterations,
            "solver_time_limit": self.solver_time_limit,
            "label": self.label,
        }
        return data


@dataclass
class SimulationResult:
    summary: dict
    samples: list[float]
    elapsed_seconds: float
    fingerprint: str


def _stable_key(seed: int, key: str) -> int:
    digest = hashlib.sha256(key.encode()).digest()
    return seed * 1_000_003 + int.from_bytes(digest[:8], "big") % (2**61 - 1)


def _uniforms(seed: int, key: str, n: int) -> np.ndarray:
    rng = np.random.default_rng(_stable_key(seed, key))
    return np.clip(rng.random(n), 1e-9, 1 - 1e-9)


def _normals(seed: int, key: str, n: int) -> np.ndarray:
    rng = np.random.default_rng(_stable_key(seed, key))
    return rng.standard_normal(n)


def wilson_interval(successes: int, n: int, z: float = 1.959963984540054) -> tuple[float, float]:
    if n <= 0:
        return (0.0, 0.0)
    p = successes / n
    denom = 1 + z * z / n
    centre = (p + z * z / (2 * n)) / denom
    half = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / denom
    return (max(0.0, centre - half), min(1.0, centre + half))


def _pct(values: np.ndarray, q: float) -> float:
    return float(np.percentile(values, q, method="linear"))


def _pearson(a: np.ndarray, b: np.ndarray) -> float:
    if a.size < 3 or np.std(a) < 1e-12 or np.std(b) < 1e-12:
        return 0.0
    return float(np.corrcoef(a, b)[0, 1])


def _correlated_uniform(seed: int, key: str, group: str | None, n: int, rho: float) -> np.ndarray:
    if not group:
        return _uniforms(seed, key, n)
    shared = _normals(seed, f"group::{group}", n)
    idio = _normals(seed, f"idio::{key}", n)
    z = rho * shared + math.sqrt(max(0.0, 1 - rho * rho)) * idio
    return np.clip(stats.norm.cdf(z), 1e-9, 1 - 1e-9)


def _impact_sample(seed: int, key: str, mean: float, cv: float, n: int, distribution: str) -> np.ndarray:
    mean = max(0.0, float(mean))
    if mean == 0:
        return np.zeros(n)
    if distribution == "fixed":
        return np.full(n, mean)
    sigma = math.sqrt(math.log(1 + cv * cv))
    mu = math.log(max(1e-9, mean)) - 0.5 * sigma**2
    return stats.lognorm.ppf(_uniforms(seed, key, n), s=sigma, scale=math.exp(mu))


def _build_params(context: SimulationContext) -> tuple[dict[str, DurationParams], list[str]]:
    params: dict[str, DurationParams] = {}
    errors: list[str] = []
    for task in context.model.tasks:
        try:
            params[task.id] = make_params(
                task.distribution,
                task.duration,
                task.duration_min,
                task.duration_mode,
                task.duration_max,
                task.std_dev,
            )
            if task.distribution != "fixed" and task.duration <= 0:
                errors.append(f"{task.code}: stochastic duration must be > 0")
        except InvalidDistribution as exc:
            errors.append(f"{task.code} ({task.name}): {exc}")
    return params, errors


def run_monte_carlo(context: SimulationContext, options: SimulationOptions | None = None) -> SimulationResult:
    options = options or SimulationOptions()
    started = time.perf_counter()
    model = context.model
    calendar = context.calendar
    tasks = model.tasks
    task_ids = [t.id for t in tasks]
    n = int(options.iterations)
    if n < 50:
        raise InvalidDistribution("At least 50 iterations are required for stable percentiles")
    if len(tasks) == 0:
        raise InvalidDistribution("Project has no tasks to simulate")

    params, param_errors = _build_params(context)
    if param_errors:
        raise InvalidDistribution("Invalid input distributions: " + "; ".join(param_errors[:6]))

    cpm: CpmResult = compute_cpm(model, calendar)
    if not cpm.validation.get("valid", False):
        raise InvalidDistribution("Invalid dependency graph: " + "; ".join(cpm.validation["errors"][:4]))
    sgs_base = schedule_sgs(model, calendar=calendar, cpm=cpm)
    priorities = sorted(task_ids, key=lambda tid: cpm.tasks[tid].latest_finish)

    # ---------------------------------------------------------------- sampling
    task_index = {tid: i for i, tid in enumerate(task_ids)}
    duration = np.zeros((n, len(task_ids)), dtype=np.float64)
    for task in tasks:
        uniforms = _correlated_uniform(
            options.seed, f"task::{task.id}", task.correlation_group if hasattr(task, "correlation_group") else None,
            n, options.correlation_rho,
        )
        values = _duration_from_params(params[task.id], uniforms)
        duration[:, task_index[task.id]] = values + max(0.0, task.buffer)

    supplier_ids = sorted(context.suppliers)
    supplier_index = {sid: i for i, sid in enumerate(supplier_ids)}
    disrupted = np.zeros((n, len(supplier_ids)), dtype=bool)
    disruption_delay = np.zeros((n, len(supplier_ids)), dtype=np.float64)
    for sid in supplier_ids:
        supplier = context.suppliers[sid]
        if not options.supplier_disruption_enabled:
            continue
        uniforms = _correlated_uniform(
            options.seed, f"supplier::{sid}", supplier.category, n, options.correlation_rho
        )
        disrupted[:, supplier_index[sid]] = uniforms < max(0.0, min(1.0, supplier.disruption_prob))
        disruption_delay[:, supplier_index[sid]] = _impact_sample(
            options.seed, f"supplier-delay::{sid}", supplier.disruption_delay_days, 0.45, n, "lognormal"
        )

    # Material release per trial.
    material = np.zeros((n, len(task_ids)), dtype=np.float64)
    material_detail: dict[str, np.ndarray] = {}
    if options.material_constraints_enabled:
        for task in tasks:
            if not task.materials:
                continue
            ready = np.zeros(n)
            for need in task.materials:
                supplier = context.suppliers.get(need.supplier_id) if need.supplier_id else None
                lead_mean = supplier.lead_time_days if supplier else need.lead_time_days
                cv = supplier.lead_time_cv if supplier else 0.2
                lead = _impact_sample(
                    options.seed, f"lead::{need.component_id}", max(0.5, lead_mean), max(0.01, cv), n, "lognormal"
                )
                lead = np.maximum(0.0, lead - need.inventory_days - need.safety_stock_days)
                if need.supplier_id and need.supplier_id in supplier_index:
                    idx = supplier_index[need.supplier_id]
                    delay = disruption_delay[:, idx]
                    if need.alternative_supplier_id and need.alternative_supplier_id in context.suppliers:
                        alt = context.suppliers[need.alternative_supplier_id]
                        if alt.qualified:
                            delay = delay * 0.35
                    lead = np.where(disrupted[:, idx], lead + delay, lead)
                ready = np.maximum(ready, lead)
                material_detail[need.component_id] = lead
            material[:, task_index[task.id]] = ready

    # Transport delay event.
    transport = _uniforms(options.seed, "event::transport", n) < options.transport_delay_prob
    transport_delay = _impact_sample(options.seed, "transport-delay", 4.0, 0.5, n, "lognormal") * transport
    material += transport_delay[:, None] * (material > 0)

    # Validation failures.
    validation_specs = [v for v in context.validations if v.task_id in task_index]
    validation_failure = np.zeros((n, len(validation_specs)), dtype=bool)
    for j, spec in enumerate(validation_specs):
        uniforms = _correlated_uniform(
            options.seed, f"validation::{spec.id}", spec.correlation_group, n, options.correlation_rho
        )
        fail = uniforms < max(0.0, min(1.0, spec.failure_probability))
        validation_failure[:, j] = fail
        duration[fail, task_index[spec.task_id]] += max(0.0, spec.retest_days)

    # Engineering change orders.
    eco_triggered = np.zeros((n, len(context.ecos)), dtype=bool)
    for j, eco in enumerate(context.ecos):
        uniforms = _uniforms(options.seed, f"eco::{eco.id}", n)
        trigger = uniforms < max(0.0, min(1.0, eco.probability))
        eco_triggered[:, j] = trigger
        targets = [tid for tid in eco.impact_task_ids if tid in task_index]
        if targets and eco.rework_days > 0:
            share = eco.rework_days / len(targets)
            for tid in targets:
                duration[trigger, task_index[tid]] += share

    # Additional discrete risks (task / supplier / component / project targets).
    risk_specs = list(context.risks)
    risk_triggered = np.zeros((n, len(risk_specs)), dtype=bool)
    risk_delay = np.zeros((n, len(risk_specs)), dtype=np.float64)
    for j, risk in enumerate(risk_specs):
        uniforms = _correlated_uniform(
            options.seed, f"risk::{risk.id}", risk.correlation_group, n, options.correlation_rho
        )
        trigger = uniforms < max(0.0, min(1.0, risk.probability))
        risk_triggered[:, j] = trigger
        impact = _impact_sample(
            options.seed, f"risk-impact::{risk.id}", risk.impact_days,
            0.35 if risk.distribution != "fixed" else 0.0, n, risk.distribution
        )
        risk_delay[:, j] = np.where(trigger, impact, 0.0)
        if risk.target_type == "task" and risk.target_id in task_index:
            duration[:, task_index[risk.target_id]] += risk_delay[:, j]
        elif risk.target_type == "supplier" and risk.target_id in supplier_index:
            affected = [
                cid for cid, comp in context.components.items() if comp.supplier_id == risk.target_id
            ]
            for cid in affected:
                for tid, mats in context.task_materials.items():
                    if tid in task_index and any(m.component_id == cid for m in mats):
                        material[:, task_index[tid]] += risk_delay[:, j]
        elif risk.target_type == "component":
            for tid, mats in context.task_materials.items():
                if tid in task_index and any(m.component_id == risk.target_id for m in mats):
                    material[:, task_index[tid]] += risk_delay[:, j]
        elif risk.target_type == "project" and task_ids:
            duration += (risk_delay[:, j] / max(1, len(task_ids)))[:, None]

    # Capacity loss and absenteeism inflate durations (never make the model infeasible).
    resource_ids = sorted(context.model.resource_map())
    capacity_loss = np.zeros((n, len(resource_ids)), dtype=bool)
    if options.capacity_loss_prob > 0:
        affected_resource = np.floor(_uniforms(options.seed, "event::capacity", n) * max(1, len(resource_ids)))
        severity = 0.15 + 0.35 * _uniforms(options.seed, "event::capacity-severity", n)
        loss_event = _uniforms(options.seed, "event::capacity-trigger", n) < options.capacity_loss_prob
        for rid in resource_ids:
            tasks_on = [i for i, t in enumerate(tasks) if any(r == rid for r, _ in t.resources)]
            rid_index = resource_ids.index(rid)
            hit = loss_event & (affected_resource == rid_index)
            capacity_loss[:, rid_index] = hit
            if tasks_on:
                duration[np.ix_(hit, tasks_on)] *= (1 + severity[hit])[:, None]
    absenteeism = _uniforms(options.seed, "event::absenteeism", n) < options.absenteeism_prob
    if absenteeism.any():
        team_tasks = [i for i, t in enumerate(tasks) if t.resources]
        if team_tasks:
            factor = 1 + 0.12 * _uniforms(options.seed, "event::absenteeism-factor", n)
            duration[np.ix_(absenteeism, team_tasks)] *= factor[absenteeism][:, None]

    # Deterministic floor: no negative or NaN durations.
    duration = np.nan_to_num(duration, nan=0.0, posinf=0.0, neginf=0.0)
    duration = np.maximum(duration, 0.0)

    if options.progress_callback:
        options.progress_callback(0.12, "Sampled stochastic inputs")

    # ------------------------------------------------------------- simulation
    makespans = np.zeros(n)
    starts = np.zeros((n, len(task_ids)), dtype=np.float32)
    ends = np.zeros((n, len(task_ids)), dtype=np.float32)
    critical_hits = np.zeros(len(task_ids))
    delay_costs = np.zeros(n)
    disruption_costs = np.zeros(n)
    risk_costs = np.zeros(n)
    retest_costs = np.zeros(n)
    eco_costs = np.zeros(n)
    ramp_costs = np.zeros(n)
    infeasible_trials = 0
    deadline_offset = model.deadline_offset

    component_spend = {
        sid: sum(
            c.unit_cost * c.qty_per_unit for c in context.components.values() if c.supplier_id == sid
        )
        for sid in supplier_ids
    }

    for i in range(n):
        if options.cancel_check and i % 25 == 0 and options.cancel_check():
            raise SimulationCancelled("Simulation cancelled by user")
        durations = {tid: float(duration[i, idx]) for tid, idx in task_index.items()}
        ready = (
            {tid: float(material[i, idx]) for tid, idx in task_index.items()}
            if options.material_constraints_enabled
            else {}
        )
        schedule = schedule_sgs(
            model, durations, calendar, cpm, priorities, material_ready=ready
        )
        if not schedule.feasible:
            infeasible_trials += 1
        makespans[i] = schedule.makespan if math.isfinite(schedule.makespan) else duration[i].sum()
        for tid in task_ids:
            idx = task_index[tid]
            starts[i, idx] = schedule.starts.get(tid, 0.0)
            ends[i, idx] = schedule.ends.get(tid, 0.0)
        for tid in schedule.critical_chain:
            if tid in task_index:
                critical_hits[task_index[tid]] += 1

        late = max(0.0, makespans[i] - deadline_offset) if deadline_offset is not None else 0.0
        delay_costs[i] = late * context.delay_cost_per_day
        disruption_costs[i] = sum(
            component_spend.get(sid, 0.0) * 0.15 * 100
            for sid in supplier_ids
            if disrupted[i, supplier_index[sid]]
        )
        risk_costs[i] = sum(
            risk.impact_cost for j, risk in enumerate(risk_specs) if risk_triggered[i, j]
        )
        retest_costs[i] = sum(
            spec.retest_days * RETEST_DAY_COST
            for j, spec in enumerate(validation_specs)
            if validation_failure[i, j]
        )
        eco_costs[i] = sum(
            eco.cost + eco.rework_days * ECO_LABOR_DAY_COST
            for j, eco in enumerate(context.ecos)
            if eco_triggered[i, j]
        )
        ramp_penalty = (context.yield_target - context.yield_start) * context.planned_volume * context.unit_margin
        ramp_costs[i] = late / max(1, context.ramp_days) * ramp_penalty * 0.1

        if options.progress_callback and i % max(1, n // 40) == 0:
            options.progress_callback(0.12 + 0.78 * i / n, f"Simulating trial {i + 1}/{n}")

    elapsed = time.perf_counter() - started

    # --------------------------------------------------------------- aggregate
    deadline_prob = 0.0
    deadline_hits = 0
    if deadline_offset is not None:
        deadline_hits = int(np.sum(makespans <= deadline_offset + 1e-9))
        deadline_prob = deadline_hits / n

    base_project_cost = sum(t.cost for t in tasks)
    incremental_cost = delay_costs + disruption_costs + risk_costs + retest_costs + eco_costs + ramp_costs
    total_cost = base_project_cost + incremental_cost

    hist_counts, hist_edges = np.histogram(makespans, bins=min(40, max(10, int(math.sqrt(n)))))
    running = np.cumsum(makespans) / np.arange(1, n + 1)
    step = max(1, n // 120)
    batch = 20
    batch_size = n // batch
    batch_se = (
        float(np.std([makespans[k * batch_size:(k + 1) * batch_size].mean() for k in range(batch)], ddof=1)
              / math.sqrt(batch))
        if batch_size > 1 else float(np.std(makespans, ddof=1) / math.sqrt(n))
    )
    rel_se = batch_se / max(1e-9, float(np.mean(makespans)))
    sem = float(np.std(makespans, ddof=1) / math.sqrt(n)) if n > 1 else 0.0

    # Milestones
    milestone_rows = []
    for m in context.milestones:
        if not m.task_id or m.task_id not in task_index:
            continue
        idx = task_index[m.task_id]
        finishes = ends[:, idx]
        row = {
            "id": m.id,
            "name": m.name,
            "task_id": m.task_id,
            "due_date": m.due_date,
            "due_offset": m.due_offset,
            "customer_commitment": m.customer_commitment,
            "mean_finish_date": calendar.to_date(float(np.mean(finishes))).isoformat(),
            "p50_date": calendar.to_date(_pct(finishes, 50)).isoformat(),
            "p80_date": calendar.to_date(_pct(finishes, 80)).isoformat(),
            "p90_date": calendar.to_date(_pct(finishes, 90)).isoformat(),
            "p10_date": calendar.to_date(_pct(finishes, 10)).isoformat(),
            "p50_offset": _pct(finishes, 50),
            "p90_offset": _pct(finishes, 90),
            "slack_vs_due_days": round(m.due_offset - float(np.mean(finishes)), 2)
            if m.due_offset is not None else None,
        }
        if m.due_offset is not None:
            hits = int(np.sum(finishes <= m.due_offset + 1e-9))
            low, high = wilson_interval(hits, n)
            row.update(
                {
                    "on_time_probability": hits / n,
                    "on_time_ci_low": low,
                    "on_time_ci_high": high,
                    "expected_delay_days": float(np.mean(np.maximum(0.0, finishes - m.due_offset))),
                }
            )
        milestone_rows.append(row)

    # Task statistics and criticality index
    task_rows = []
    task_names = {t.id: t.name for t in tasks}
    for task in tasks:
        idx = task_index[task.id]
        duration_col = duration[:, idx]
        start_col = starts[:, idx]
        end_col = ends[:, idx]
        task_rows.append(
            {
                "id": task.id,
                "code": task.code,
                "name": task.name,
                "phase": task.phase,
                "mean_duration": round(float(np.mean(duration_col)), 2),
                "std_duration": round(float(np.std(duration_col, ddof=1)), 3),
                "p90_duration": round(_pct(duration_col, 90), 2),
                "mean_start_offset": round(float(np.mean(start_col)), 2),
                "mean_finish_offset": round(float(np.mean(end_col)), 2),
                "p50_finish_date": calendar.to_date(_pct(end_col, 50)).isoformat(),
                "p90_finish_date": calendar.to_date(_pct(end_col, 90)).isoformat(),
                "criticality_index": round(critical_hits[idx] / n, 4),
                "is_gate": task.is_gate,
            }
        )
    task_rows.sort(key=lambda r: (-r["criticality_index"], -r["p90_duration"]))

    # Supplier risk analysis
    supplier_rows = []
    makespan_gt_deadline = (makespans > deadline_offset) if deadline_offset is not None else np.zeros(n, bool)
    for sid in supplier_ids:
        supplier = context.suppliers[sid]
        idx = supplier_index[sid]
        hit = disrupted[:, idx]
        affected_components = [
            c.name for c in context.components.values() if c.supplier_id == sid
        ]
        affected_tasks = [
            task_names[tid]
            for tid, mats in context.task_materials.items()
            if any(
                context.components[m.component_id].supplier_id == sid
                for m in mats
                if m.component_id in context.components
            )
        ]
        conditional_delay = (
            float(np.mean(makespans[hit])) - float(np.mean(makespans[~hit]))
            if hit.any() and (~hit).any() else 0.0
        )
        supplier_rows.append(
            {
                "id": sid,
                "name": supplier.name,
                "category": supplier.category,
                "region": supplier.region,
                "reliability": supplier.reliability,
                "input_disruption_probability": supplier.disruption_prob,
                "observed_disruption_rate": float(hit.mean()),
                "conditional_delay_days": round(conditional_delay, 2),
                "expected_delay_contribution_days": round(conditional_delay * float(hit.mean()), 2),
                "probability_impacting_launch": float(np.mean(hit & makespan_gt_deadline)),
                "expected_disruption_cost": round(
                    component_spend.get(sid, 0.0) * 0.15 * 100 * float(hit.mean()), 2
                ),
                "affected_components": affected_components,
                "affected_tasks": affected_tasks[:8],
                "single_source_components": sum(
                    1 for c in context.components.values() if c.supplier_id == sid and c.single_source
                ),
            }
        )
    supplier_rows.sort(key=lambda r: -r["expected_delay_contribution_days"])

    # Discrete risk analysis
    risk_rows = []
    for j, risk in enumerate(risk_specs):
        hit = risk_triggered[:, j]
        conditional = (
            float(np.mean(makespans[hit])) - float(np.mean(makespans[~hit]))
            if hit.any() and (~hit).any() else 0.0
        )
        risk_rows.append(
            {
                "id": risk.id,
                "name": risk.name,
                "category": risk.category,
                "target_type": risk.target_type,
                "target_id": risk.target_id,
                "input_probability": risk.probability,
                "observed_trigger_rate": float(hit.mean()),
                "conditional_delay_days": round(conditional, 2),
                "expected_delay_contribution_days": round(conditional * float(hit.mean()), 2),
                "probability_of_launch_impact": float(np.mean(hit & makespan_gt_deadline)),
                "expected_impact_cost": round(risk.impact_cost * float(hit.mean()), 2),
            }
        )
    risk_rows.sort(key=lambda r: -r["expected_delay_contribution_days"])

    # Rank-correlation sensitivity (sampled task duration vs makespan).
    spearman_rows = []
    for task in tasks:
        idx = task_index[task.id]
        col = duration[:, idx]
        if np.std(col) < 1e-9:
            corr, p_value = 0.0, 1.0
        else:
            result = stats.spearmanr(col, makespans)
            corr = float(result.statistic) if np.isfinite(result.statistic) else 0.0
            p_value = float(result.pvalue) if np.isfinite(result.pvalue) else 1.0
        spearman_rows.append(
            {
                "input": task.name,
                "input_id": task.id,
                "kind": "task_duration",
                "correlation": round(corr, 4),
                "abs_correlation": round(abs(corr), 4),
                "p_value": p_value,
                "method": "Spearman rank correlation",
            }
        )
    for j, risk in enumerate(risk_specs):
        corr = _pearson(risk_triggered[:, j].astype(float), makespans)
        spearman_rows.append(
            {
                "input": risk.name,
                "input_id": risk.id,
                "kind": "risk_event",
                "correlation": round(corr, 4),
                "abs_correlation": round(abs(corr), 4),
                "p_value": None,
                "method": "Point-biserial correlation",
            }
        )
    for sid in supplier_ids:
        idx = supplier_index[sid]
        corr = _pearson(disrupted[:, idx].astype(float), makespans)
        spearman_rows.append(
            {
                "input": f"Supplier disruption: {context.suppliers[sid].name}",
                "input_id": sid,
                "kind": "supplier_disruption",
                "correlation": round(corr, 4),
                "abs_correlation": round(abs(corr), 4),
                "p_value": None,
                "method": "Point-biserial correlation",
            }
        )
    spearman_rows.sort(key=lambda r: -r["abs_correlation"])

    # Deterministic one-at-a-time tornado.
    tornado_rows = _tornado(context, cpm, priorities)

    # Dependency criticality frequencies from realised schedules.
    dependency_rows = []
    for edge in model.edges:
        if edge.from_id not in task_index or edge.to_id not in task_index:
            continue
        fi, ti = task_index[edge.from_id], task_index[edge.to_id]
        if edge.type == "FS":
            driving = np.abs(starts[:, ti] - (ends[:, fi] + edge.lag)) < 0.5
        elif edge.type == "SS":
            driving = np.abs(starts[:, ti] - (starts[:, fi] + edge.lag)) < 0.5
        elif edge.type == "FF":
            driving = np.abs(ends[:, ti] - (ends[:, fi] + edge.lag)) < 0.5
        else:
            driving = np.abs(ends[:, ti] - (starts[:, fi] + edge.lag)) < 0.5
        dependency_rows.append(
            {
                "from": task_names.get(edge.from_id, edge.from_id),
                "to": task_names.get(edge.to_id, edge.to_id),
                "from_id": edge.from_id,
                "to_id": edge.to_id,
                "type": edge.type,
                "lag": edge.lag,
                "frequency": round(float(np.mean(driving)), 4),
            }
        )
    dependency_rows.sort(key=lambda r: -r["frequency"])

    # Completion-date curve.
    curve_offsets = np.linspace(float(np.min(makespans)), float(np.max(makespans)), 25)
    completion_curve = [
        {
            "offset": round(float(offset), 2),
            "date": calendar.to_date(float(offset)).isoformat(),
            "probability": float(np.mean(makespans <= offset)),
        }
        for offset in curve_offsets
    ]

    cvar_90 = float(np.mean(makespans[makespans >= _pct(makespans, 90)]))
    summary = {
        "engine": {
            "version": ENGINE_VERSION,
            "scheduler": "serial_sgs (resource- and material-feasible)",
            "iterations": n,
            "seed": options.seed,
            "elapsed_seconds": round(elapsed, 3),
            "trials_per_second": round(n / max(elapsed, 1e-6), 1),
            "percentile_method": PERCENTILE_METHOD,
            "infeasible_trials": infeasible_trials,
            "options": options.to_dict(),
        },
        "makespan": {
            "mean": round(float(np.mean(makespans)), 2),
            "std": round(float(np.std(makespans, ddof=1)), 2),
            "min": round(float(np.min(makespans)), 2),
            "max": round(float(np.max(makespans)), 2),
            "p10": round(_pct(makespans, 10), 2),
            "p50": round(_pct(makespans, 50), 2),
            "p80": round(_pct(makespans, 80), 2),
            "p90": round(_pct(makespans, 90), 2),
            "p95": round(_pct(makespans, 95), 2),
            "cvar90": round(cvar_90, 2),
            "sem": round(sem, 3),
            "ci95_mean": [
                round(float(np.mean(makespans)) - 1.96 * sem, 2),
                round(float(np.mean(makespans)) + 1.96 * sem, 2),
            ],
            "p50_date": calendar.to_date(_pct(makespans, 50)).isoformat(),
            "p80_date": calendar.to_date(_pct(makespans, 80)).isoformat(),
            "p90_date": calendar.to_date(_pct(makespans, 90)).isoformat(),
        },
        "deadline": {
            "date": context.deadline_date.isoformat() if context.deadline_date else None,
            "offset": deadline_offset,
            "on_time_probability": round(deadline_prob, 4),
            "on_time_ci": list(wilson_interval(deadline_hits, n)) if deadline_offset is not None else None,
            "expected_delay_days": round(
                float(np.mean(np.maximum(0.0, makespans - deadline_offset))), 2
            ) if deadline_offset is not None else 0.0,
            "p90_delay_days": round(
                _pct(np.maximum(0.0, makespans - deadline_offset), 90), 2
            ) if deadline_offset is not None else 0.0,
            "probability_of_delay": round(float(np.mean(makespan_gt_deadline)), 4),
            "expected_delay_cost": round(float(np.mean(delay_costs)), 2),
            "p90_delay_cost": round(_pct(delay_costs, 90), 2),
            "cost_at_risk": round(float(np.mean(total_cost)), 2),
            "cvar90_delay_cost": round(
                float(np.mean(delay_costs[delay_costs >= _pct(delay_costs, 90)])), 2
            ),
        },
        "cost": {
            "currency": context.currency,
            "base_project_cost": round(base_project_cost, 2),
            "expected_incremental_cost": round(float(np.mean(incremental_cost)), 2),
            "p90_incremental_cost": round(_pct(incremental_cost, 90), 2),
            "expected_total_cost": round(float(np.mean(total_cost)), 2),
            "p90_total_cost": round(_pct(total_cost, 90), 2),
            "breakdown": {
                "delay": round(float(np.mean(delay_costs)), 2),
                "supplier_disruption": round(float(np.mean(disruption_costs)), 2),
                "risk_events": round(float(np.mean(risk_costs)), 2),
                "retest": round(float(np.mean(retest_costs)), 2),
                "eco_rework": round(float(np.mean(eco_costs)), 2),
                "ramp_yield": round(float(np.mean(ramp_costs)), 2),
            },
        },
        "histogram": {
            "counts": hist_counts.tolist(),
            "bin_edges": [round(float(x), 2) for x in hist_edges],
        },
        "convergence": {
            "running_mean": [round(float(x), 3) for x in running[::step]],
            "x": list(range(1, n + 1, step)),
            "batch_means_se": round(batch_se, 4),
            "relative_se": round(rel_se, 5),
            "converged": rel_se < 0.01,
            "criterion": "batch-means relative standard error < 1% of the mean",
            "recommended_iterations": int(min(50000, max(500, math.ceil((float(np.std(makespans, ddof=1)) / (0.01 * max(1e-6, float(np.mean(makespans))))) ** 2)))),
        },
        "milestones": milestone_rows,
        "tasks": task_rows,
        "suppliers": supplier_rows,
        "risks": risk_rows,
        "attribution": {
            "sensitivity": spearman_rows[:20],
            "tornado": tornado_rows,
            "dependency_criticality": dependency_rows[:20],
            "notes": [
                "Rank correlation measures monotonic association, not causation.",
                "Tornado impacts are deterministic one-at-a-time schedule recomputations (+/-20% duration, +/-30% supplier lead time).",
                "Dependency criticality is the share of trials in which an edge exactly binds its successor.",
            ],
        },
        "completion_curve": completion_curve,
        "calendar": {
            "start_date": context.model.start_date.isoformat(),
            "working_days_per_week": calendar.working_days_per_week,
        },
        "assumptions": context.assumptions
        + [
            f"Supplier disruption probability is applied per trial; delay is lognormal with mean {np.mean(disruption_delay) if disruption_delay.size else 0:.2f} working days.",
            f"Retest cost assumption: {RETEST_DAY_COST:,.0f} {context.currency}/day; ECO labour: {ECO_LABOR_DAY_COST:,.0f}/day.",
            "Ramp yield cost is a planning estimate of margin lost during ramp extension.",
        ],
        "warnings": _warnings(context, cpm, sgs_base, options, infeasible_trials),
        "inputs": {
            "task_count": len(tasks),
            "dependency_count": len(model.edges),
            "resource_count": len(model.resources),
            "supplier_count": len(supplier_ids),
            "risk_count": len(risk_specs),
            "validation_count": len(validation_specs),
            "eco_count": len(context.ecos),
            "milestone_count": len(milestone_rows),
        },
        "deterministic": {
            "cpm_makespan": round(cpm.project_duration, 2),
            "cpm_finish_date": cpm.finish_date,
            "sgs_base_makespan": round(sgs_base.makespan, 2),
            "sgs_critical_path": [task_names.get(t, t) for t in sgs_base.critical_chain],
            "capacity_delay_days": round(sgs_base.makespan - cpm.project_duration, 2),
        },
    }

    if options.validate_iterations > 0:
        summary["solver_validation"] = _validate_against_cpsat(
            context, duration, task_index, options
        )

    if options.progress_callback:
        options.progress_callback(0.95, "Aggregating results")

    sampled = [round(float(x), 4) for x in makespans]
    if len(sampled) > 20000:
        sampled = sampled[:20000]
    return SimulationResult(
        summary=summary,
        samples=sampled,
        elapsed_seconds=elapsed,
        fingerprint=_fingerprint(context, options),
    )


def _duration_from_params(params: DurationParams, uniforms: np.ndarray) -> np.ndarray:
    from app.simulation.distributions import duration_ppf

    return np.asarray(duration_ppf(params, uniforms), dtype=np.float64)


def _tornado(context: SimulationContext, cpm: CpmResult, priorities: list[str]) -> list[dict]:
    model = context.model
    base = {t.id: t.base_duration for t in model.tasks}
    base_makespan = schedule_sgs(model, base, context.calendar, cpm, priorities).makespan
    rows = []
    for task in model.tasks:
        if task.base_duration <= 0:
            continue
        low = dict(base)
        high = dict(base)
        low[task.id] = task.base_duration * 0.8
        high[task.id] = task.base_duration * 1.2
        low_span = schedule_sgs(model, low, context.calendar, cpm, priorities).makespan
        high_span = schedule_sgs(model, high, context.calendar, cpm, priorities).makespan
        rows.append(
            {
                "input": task.name,
                "input_id": task.id,
                "kind": "task_duration",
                "low_case": round(low_span, 2),
                "high_case": round(high_span, 2),
                "base": round(base_makespan, 2),
                "delta_days": round(high_span - low_span, 2),
                "base_delta_days": round(high_span - base_makespan, 2),
            }
        )
    for sid, supplier in context.suppliers.items():
        affected = [
            tid for tid, mats in context.task_materials.items()
            if any(
                context.components[m.component_id].supplier_id == sid
                for m in mats
                if m.component_id in context.components
            )
        ]
        if not affected:
            continue
        base_ready = dict(model.material_ready)
        low_ready = dict(base_ready)
        high_ready = dict(base_ready)
        for tid in affected:
            low_ready[tid] = max(0.0, base_ready.get(tid, 0.0) - supplier.lead_time_days * 0.15)
            high_ready[tid] = base_ready.get(tid, 0.0) + supplier.lead_time_days * 0.3
        low_span = schedule_sgs(model, base, context.calendar, cpm, priorities, low_ready).makespan
        high_span = schedule_sgs(model, base, context.calendar, cpm, priorities, high_ready).makespan
        rows.append(
            {
                "input": supplier.name,
                "input_id": sid,
                "kind": "supplier_lead_time",
                "low_case": round(low_span, 2),
                "high_case": round(high_span, 2),
                "base": round(base_makespan, 2),
                "delta_days": round(high_span - low_span, 2),
                "base_delta_days": round(high_span - base_makespan, 2),
            }
        )
    rows.sort(key=lambda r: -abs(r["delta_days"]))
    return rows[:15]


def _validate_against_cpsat(
    context: SimulationContext, duration: np.ndarray, task_index: dict[str, int], options: SimulationOptions
) -> dict:
    """Compare SGS makespan with CP-SAT optimum on a sample of simulated trials."""
    count = min(max(1, options.validate_iterations), 10)
    gaps = []
    statuses = []
    for i in range(count):
        tasks = []
        for task in context.model.tasks:
            sampled = float(duration[i, task_index[task.id]])
            tasks.append(
                TaskNode(
                    **{
                        **task.__dict__,
                        "duration": sampled,
                        "distribution": "fixed",
                        "duration_min": None,
                        "duration_mode": None,
                        "duration_max": None,
                        "std_dev": None,
                        "buffer": 0.0,
                    }
                )
            )
        sampled_model = PlanningModel(
            project_id=context.model.project_id,
            start_date=context.model.start_date,
            tasks=tasks,
            edges=context.model.edges,
            resources=context.model.resources,
            material_ready=context.model.material_ready,
            deadline_offset=None,
            delay_cost_per_day=context.model.delay_cost_per_day,
        )
        sgs = schedule_sgs(sampled_model, calendar=context.calendar)
        cp = resource_constrained_schedule(
            sampled_model,
            context.calendar,
            CpsatOptions(time_limit_seconds=min(3.0, options.solver_time_limit), compute_float=False),
        )
        if cp.get("feasible") and cp.get("makespan"):
            gap = sgs.makespan - float(cp["makespan"])
            gaps.append(gap)
            statuses.append(cp["status"])
        else:
            gaps.append(None)
            statuses.append(cp.get("status", "UNKNOWN"))
    valid_gaps = [g for g in gaps if g is not None]
    return {
        "trials_validated": count,
        "statuses": statuses,
        "mean_gap_days": round(float(np.mean(valid_gaps)), 3) if valid_gaps else None,
        "max_gap_days": round(float(np.max(valid_gaps)), 3) if valid_gaps else None,
        "gaps_days": [round(g, 3) if g is not None else None for g in gaps],
        "note": "SGS is a feasibility-preserving heuristic; non-negative gaps are expected and bounded here.",
    }


def _warnings(context, cpm, sgs_base, options, infeasible_trials) -> list[str]:  # noqa: ANN001
    warnings = []
    if infeasible_trials:
        warnings.append(f"{infeasible_trials} trial(s) produced capacity conflicts; inspect resource demands.")
    if sgs_base.makespan - cpm.project_duration > 1:
        warnings.append(
            f"Resource capacity adds {sgs_base.makespan - cpm.project_duration:.0f} working days beyond the unconstrained critical path."
        )
    if options.iterations < 500:
        warnings.append("Fewer than 500 iterations: percentile estimates may be unstable.")
    if not context.milestones:
        warnings.append("No milestones defined; only overall launch probability is computed.")
    if context.deadline_date is None:
        warnings.append("No customer launch deadline configured; on-time probability is unavailable.")
    if not context.risks and all(s.disruption_prob == 0 for s in context.suppliers.values()):
        warnings.append("No stochastic risk drivers are active; the simulation reduces to duration variability.")
    return warnings


def _fingerprint(context: SimulationContext, options: SimulationOptions) -> str:
    key = (
        context.model.project_id
        + "|"
        + str(options.seed)
        + "|"
        + str(options.iterations)
        + "|"
        + ",".join(sorted(t.id + ":" + str(t.base_duration) for t in context.model.tasks))
        + "|"
        + str(context.model.deadline_offset)
    )
    return hashlib.sha256(key.encode()).hexdigest()[:16]
